import Link from "next/link";
import snapshot from "@/lib/evaluation-snapshot.json";

export default function EvaluationPage() {
  const { summary, scenarios, sourceRevision, generatedAt } = snapshot;
  const allPassed = summary.failed === 0;
  return <main className="evaluation-page">
    <header className="topbar"><Link className="brand" href="/" aria-label="MarginGhost home"><span className="brand-icon">M</span><span>MarginGhost <small>V0.4</small></span></Link><nav className="main-nav" aria-label="Main navigation"><Link href="/">Overview</Link><Link href="/investigate">Investigate</Link><Link href="/demo">Synthetic demo</Link><Link href="/evaluation" aria-current="page">Evaluation</Link></nav><Link className="nav-cta" href="/investigate">Open workspace <span aria-hidden="true">→</span></Link></header>
    <section className="evaluation-hero"><div className="eyebrow"><span className="dot"/> DETERMINISTIC REGRESSION · READ ONLY</div><h1>Reliability under adversarial conditions.</h1><p>Fixed, version-controlled scenarios run through MarginGhost’s citation verification and deterministic decision path. This evaluates safety behavior; it is not a benchmark of LLM accuracy.</p><div className="evaluation-tags"><span>No arbitrary inputs</span><span>No inference calls</span><span>Reproducible fixture run</span></div></section>
    <section className="evaluation-summary" aria-label="Evaluation summary"><div className={`evaluation-status ${allPassed ? "good" : "bad"}`}><span>{allPassed ? "●" : "●"}</span><div><small>RUN OUTCOME</small><strong>{allPassed ? "All expected outcomes observed" : "One or more outcomes differ"}</strong></div></div><div className="evaluation-metric"><small>ADVERSARIAL SCENARIOS PASSED</small><strong>{summary.passed} <i>/ {summary.scenarios}</i></strong></div><div className="evaluation-metric"><small>UNSUPPORTED CLAIMS SAFELY WITHHELD</small><strong>{summary.unsupportedClaimsSafelyWithheld}</strong></div></section>
    <div className="evaluation-heading"><div><span className="section-kicker">CASE-BY-CASE RESULTS</span><h2>Expected against actual</h2></div><p>Each row shows the observed disposition from a deterministic run, including failures.</p></div>
    <section className="evaluation-cases">{scenarios.map(row => <article className="evaluation-case" key={row.id}><div className="evaluation-case-top"><div><span className="case-number">{row.id.toUpperCase()}</span><h3>{row.name}</h3></div><span className={`case-result ${row.passed ? "pass" : "fail"}`}>{row.passed ? "PASS" : "FAIL"}</span></div><p className="case-condition"><b>Input condition</b>{row.condition}</p><div className="case-dispositions"><div><small>EXPECTED</small><strong>{row.expected.replaceAll("_", " ")}</strong></div><span aria-hidden="true">→</span><div><small>ACTUAL</small><strong>{row.actual.replaceAll("_", " ")}</strong></div></div><p className="case-explanation">{row.explanation}</p><small className="case-provenance">PROVENANCE · {row.provenance}</small></article>)}</section>
    <footer className="evaluation-footer"><div><b>Deterministic regression evaluation</b><span>Generated {new Date(generatedAt).toLocaleString("en", { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" })} UTC · source revision <code>{sourceRevision.slice(0, 12)}</code></span></div><p>Reproduce with <code>npm run evaluate</code>. The JSON artifact is a generated snapshot, not live data. No precision, recall, or LLM accuracy is inferred.</p></footer>
  </main>;
}

